// Build Dropbox paths for each shoe review record.
// Also saves total count in workflow static data for the summary email.

const items = $input.all();

// Persist total for email (static data survives across nodes in same execution)
$getWorkflowStaticData('global').imageCleanup = {
  totalRecords: items.length,
  startTime: new Date().toISOString()
};

return items.map(item => {
  const record = item.json;
  // Airtable v2 node returns fields nested under .fields
  const shoeName = (record.fields?.['F_Shoe_Reviewed'] || record['F_Shoe_Reviewed'] || '').trim();
  const recordId = record.id;

  // Plain Dropbox folder path
  const plainPath = `/Sameera - RSG reviews/Pictures/${shoeName}`;

  // Clickable Dropbox web URL
  // Each path segment encoded separately, joined with /
  const webUrl =
    'https://www.dropbox.com/home/' +
    encodeURIComponent('Sameera - RSG reviews') +
    '/' + encodeURIComponent('Pictures') +
    '/' + encodeURIComponent(shoeName);

  return {
    json: {
      recordId,
      shoeName,
      dropboxWebUrl: webUrl,
      dropboxPlainPath: plainPath
    }
  };
});

// Format the current batch of up to 10 records as an Airtable PATCH body.
//
// Field IDs:
//   fldY88GWo74zWfE7Q = Images              -> clear (empty array)
//   fld7GxeuE8WX9q2eL = Edited Images       -> clear (empty array)
//   fldtW8hIvQiy1rx0G = Dropbox for images  -> set clickable web URL
//   fldQ0clyA6yw4rLoy = Dropbox plain path  -> set plain folder path

const items = $input.all();

const records = items.map(item => ({
  id: item.json.recordId,
  fields: {
    fldY88GWo74zWfE7Q: [],
    fld7GxeuE8WX9q2eL: [],
    fldtW8hIvQiy1rx0G: item.json.dropboxWebUrl,
    fldQ0clyA6yw4rLoy: item.json.dropboxPlainPath
  }
}));

return [{ json: { records } }];

// Build summary email after all batches complete.
const staticData = $getWorkflowStaticData('global');
const cleanup = staticData.imageCleanup || {};
const totalRecords = cleanup.totalRecords || 'unknown';
const startTime = cleanup.startTime
  ? new Date(cleanup.startTime).toLocaleString('nl-NL', {
      timeZone: 'Europe/Amsterdam',
      dateStyle: 'medium',
      timeStyle: 'short'
    })
  : 'unknown';

const subject = `\u2705 RSG Image Cleanup \u2014 ${totalRecords} records cleared`;

const body = [
  'RSG Shoe Review image cleanup complete.',
  '',
  `Records processed : ${totalRecords}`,
  `Cutoff            : reviews older than 3 years`,
  `Started at        : ${startTime} (Amsterdam)`,
  '',
  'Actions per record:',
  '  \u2022 Images field cleared',
  '  \u2022 Edited Images field cleared',
  '  \u2022 Dropbox web URL stored in "Dropbox for images" field (fldtW8hIvQiy1rx0G)',
  '  \u2022 Dropbox plain path stored in "Dropbox plain path" field (fldQ0clyA6yw4rLoy)',
  '',
  'Path format: /Sameera - RSG reviews/Pictures/{shoe_name}',
  '',
  'Note: Dropbox files are NOT deleted. Images remain safely in Dropbox.'
].join('\n');

return [{ json: { subject, body } }];
